"""The ``lock/v1`` runtime lock: what masked or generated bytes depend on, in one portable file.

A lock is canonical JSON of library versions, two content digests and an optional key version
label. It holds no key, no key check value, no path and no host name, so it can be copied between
hosts and compared. ``compare_runtime_locks`` names each field that differs.

One field list (``_FIELDS``) is both the writer and the reader, so the writer cannot emit what the
reader refuses. The reader refuses an unknown tag, a missing tag, a missing field and a wrong
type, and ignores a field added under ``lock/v1`` (compatibility contract 3.1). Versions come from
``runtime_identity`` and distribution metadata; digests go through the canonical JSON writer.
Pattern: lock files of resolved inputs (``uv.lock``) diffed as environment reports.
"""

from __future__ import annotations

import hashlib
import importlib.metadata as _md
import importlib.resources
import re
import warnings
from collections.abc import Sequence
from dataclasses import dataclass
from fnmatch import fnmatchcase
from typing import Any, Final, NoReturn

from decoy_engine import reasons, release
from decoy_engine._canonical import (
    CountSpec,
    ExactSpec,
    NullableSpec,
    ObjectSpec,
    OneOfSpec,
    ShapedSpec,
    Spec,
    SpecRefusedError,
    attempt,
    canonical_json_bytes,
    parse_or_token,
)
from decoy_engine.generation import runtime_identity
from decoy_engine.keyprovider import KEY_VERSION_PATTERN, MaskSecretError, is_key_version_label
from decoy_engine.publication import is_hex64

__all__ = [
    "LOCK_SCHEMA",
    "LockDifference",
    "RuntimeLock",
    "build_runtime_lock",
    "compare_runtime_locks",
    "read_runtime_lock",
]

LOCK_SCHEMA: Final = "lock/v1"
MAX_LOCK_BYTES: Final = 64 * 1024
REFUSAL_PREFIX: Final = "runtime_lock_refused:"

_MAX_INT_DIGITS: Final = 20
_MAX_SEED_PROTOCOL: Final = 255
_MAX_DEPENDENCIES: Final = 256
_VERSION_PATTERN: Final = r"[A-Za-z0-9][A-Za-z0-9._+!-]{0,63}"
_DIST_PATTERN: Final = r"[a-z0-9][a-z0-9._-]{0,63}"
_HEX64_PATTERN: Final = r"[0-9a-f]{64}"
_KEY_VERSION_MESSAGE: Final = "key_version must be 1 to 64 characters from [A-Za-z0-9._:+!-]."

# Distributions that already have their own lock field never repeat in `dependencies`.
_OWN_FIELD_DISTS: Final = frozenset({"numpy", "pandas", "pyarrow", "faker"})
# (resource package, file glob) of the shipped data the digest covers.
_DATA_PACKAGES: Final = (
    ("decoy_engine.codesets", "*.parquet"),
    ("decoy_engine.reference_tables.data", "*.parquet"),
    ("decoy_engine.generation.composite.data", "us_localities.csv"),
)

_VERSION_RE = re.compile(_VERSION_PATTERN)
_DIST_RE = re.compile(_DIST_PATTERN)


def _refuse(check: str) -> NoReturn:
    raise ValueError(REFUSAL_PREFIX + check)


def _matches(pattern: Any) -> Any:
    # fullmatch, not a `$` anchor: `$` also matches before a trailing newline.
    return lambda value: pattern.fullmatch(value) is not None


_VERSION = ShapedSpec(_VERSION_PATTERN, _matches(_VERSION_RE))
_DIGEST = ShapedSpec(_HEX64_PATTERN, is_hex64)
_KEY_VERSION = NullableSpec(ShapedSpec(KEY_VERSION_PATTERN, is_key_version_label))


@dataclass(frozen=True)
class _DependenciesSpec:
    """A JSON object of distribution name to version text; the model holds sorted pairs."""

    def load(self, raw: Any) -> tuple[tuple[str, str], ...]:
        if type(raw) is not dict:
            raise SpecRefusedError("wrong_type")
        if len(raw) > _MAX_DEPENDENCIES:
            raise SpecRefusedError("out_of_range")
        pairs = []
        for name, version in raw.items():
            ShapedSpec(_DIST_PATTERN, _matches(_DIST_RE)).load(name)
            _VERSION.load(version)
            pairs.append((name, version))
        return tuple(sorted(pairs))

    def dump(self, value: Any) -> dict[str, str]:
        if type(value) is not tuple:
            raise SpecRefusedError("wrong_type")
        out: dict[str, str] = {}
        for pair in value:
            if type(pair) is not tuple or len(pair) != 2:
                raise SpecRefusedError("wrong_type")
            name, version = pair
            if type(name) is not str or type(version) is not str:
                raise SpecRefusedError("wrong_type")
            out[name] = version
        if len(out) != len(value) or list(out) != sorted(out):
            raise SpecRefusedError("bad_token")
        return out

    def describe(self) -> str:
        return "dependencies"


_FIELDS: Final[tuple[tuple[str, Spec], ...]] = (
    ("schema", ExactSpec(LOCK_SCHEMA)),
    ("engine", _VERSION),
    ("numpy", _VERSION),
    ("pandas", _VERSION),
    ("pyarrow", _VERSION),
    ("python", _VERSION),
    ("seed_protocol", CountSpec(_MAX_SEED_PROTOCOL)),
    ("tz", _VERSION),
    ("compat_phase", OneOfSpec(("pre-ga", "ga"))),
    ("faker", _VERSION),
    ("providers_digest", _DIGEST),
    ("data_digest", _DIGEST),
    ("dependencies", _DependenciesSpec()),
    ("key_version", _KEY_VERSION),
)


@dataclass(frozen=True)
class RuntimeLock:
    """One host's runtime lock. A value that breaks the ``lock/v1`` rules is refused at construction."""

    engine: str
    numpy: str
    pandas: str
    pyarrow: str
    python: str
    seed_protocol: int
    tz: str
    compat_phase: str
    faker: str
    providers_digest: str
    data_digest: str
    dependencies: tuple[tuple[str, str], ...]
    key_version: str | None = None
    schema: str = LOCK_SCHEMA

    def __post_init__(self) -> None:
        # Raised outside any handler, so the error carries no context and no value.
        if self.key_version is not None and not is_key_version_label(self.key_version):
            raise MaskSecretError(
                code=reasons.runtime.KEY_VERSION_INVALID, message=_KEY_VERSION_MESSAGE
            )
        refused = None
        for name, spec in _FIELDS:
            _, refused = attempt(lambda v, s=spec: s.load(s.dump(v)), getattr(self, name))
            if refused is not None:
                break
        if refused is not None:
            _refuse(refused)

    def to_dict(self) -> dict[str, Any]:
        """The JSON form of the lock."""
        return {name: spec.dump(getattr(self, name)) for name, spec in _FIELDS}

    def to_json(self) -> str:
        """The canonical JSON text of the lock: sorted keys, compact, the same in every process."""
        return canonical_json_bytes(self.to_dict()).decode("utf-8")

    @classmethod
    def from_dict(cls, raw: Any) -> RuntimeLock:
        """Read a parsed lock document. A field added under ``lock/v1`` is ignored."""
        if type(raw) is not dict:
            _refuse("not_object")
        if "schema" not in raw:
            _refuse("schema_missing")
        known = {name: raw[name] for name, _ in _FIELDS if name in raw}
        lock, refused = attempt(ObjectSpec(cls, _FIELDS).load, known)
        if refused is not None:
            _refuse(refused)
        return lock  # type: ignore[no-any-return]


@dataclass(frozen=True)
class LockDifference:
    """A field whose value differs between locks; ``values`` holds one per lock, in input order."""

    field: str
    values: tuple[Any, ...]


def read_runtime_lock(data: bytes | str) -> RuntimeLock:
    """Read a stored lock, refusing a malformed one with ``runtime_lock_refused:<check>``."""
    raw = data.encode("utf-8") if type(data) is str else data
    if type(raw) is not bytes:
        _refuse("wrong_type")
    if len(raw) > MAX_LOCK_BYTES:
        _refuse("oversize")
    parsed, token = parse_or_token(raw, _MAX_INT_DIGITS)
    if token is not None:
        _refuse(token)
    return RuntimeLock.from_dict(parsed)


def _data_files() -> list[tuple[str, bytes]]:
    """Each shipped data file as ``(package-relative POSIX path, bytes)``, sorted by path.

    Read through the resource API, so no file path is built here.
    """
    found: list[tuple[str, bytes]] = []
    with warnings.catch_warnings():
        # `contents` and `read_binary` are the stable resource calls; 3.11 and 3.12 mark them
        # deprecated and 3.13 restores them.
        warnings.simplefilter("ignore", DeprecationWarning)
        for package, pattern in _DATA_PACKAGES:
            for name in importlib.resources.contents(package):
                if fnmatchcase(name, pattern):
                    relative = package.removeprefix("decoy_engine.").replace(".", "/")
                    found.append(
                        (f"{relative}/{name}", importlib.resources.read_binary(package, name))
                    )
    return sorted(found)


def _data_digest() -> str:
    pairs = [[name, hashlib.sha256(blob).hexdigest()] for name, blob in _data_files()]
    return hashlib.sha256(canonical_json_bytes(pairs)).hexdigest()


def _providers_digest() -> str:
    from decoy_engine.providers_v2 import _registry

    registry = _registry.get_default_registry()
    rows = []
    for name in sorted(registry.known_providers()):
        caps = registry.get_capabilities(name)
        rows.append([name, caps.backend_type, caps.backend_version])
    return hashlib.sha256(canonical_json_bytes(rows)).hexdigest()


def _dependency_versions() -> tuple[tuple[str, str], ...]:
    """Installed versions of the engine's declared base dependencies, from distribution metadata."""
    from packaging.requirements import Requirement
    from packaging.utils import canonicalize_name

    try:
        declared = _md.requires("decoy-engine") or []
    except _md.PackageNotFoundError:
        return ()
    found: dict[str, str] = {}
    for line in declared:
        requirement = Requirement(line)
        if requirement.marker is not None and not requirement.marker.evaluate({"extra": ""}):
            continue
        name = str(canonicalize_name(requirement.name))
        if name in _OWN_FIELD_DISTS:
            continue
        try:
            found[name] = _md.version(name)
        except _md.PackageNotFoundError:
            continue
    return tuple(sorted(found.items()))


def build_runtime_lock(*, key_version: str | None = None) -> RuntimeLock:
    """The lock of this host. ``key_version`` is an optional label, never key material."""
    identity = dict(runtime_identity())
    return RuntimeLock(
        engine=identity["engine"],
        numpy=identity["numpy"],
        pandas=identity["pandas"],
        pyarrow=identity["pyarrow"],
        python=identity["python"],
        seed_protocol=int(identity["seed_protocol"]),
        tz=identity["tz"],
        compat_phase=release.RELEASE_PHASE,
        faker=_md.version("faker"),
        providers_digest=_providers_digest(),
        data_digest=_data_digest(),
        dependencies=_dependency_versions(),
        key_version=key_version,
    )


def compare_runtime_locks(locks: Sequence[RuntimeLock]) -> tuple[LockDifference, ...]:
    """Each field whose value is not the same in every lock, in field order."""
    if any(type(lock) is not RuntimeLock for lock in locks):
        raise TypeError("compare_runtime_locks takes RuntimeLock values")
    documents = [lock.to_dict() for lock in locks]
    return tuple(
        LockDifference(name, tuple(doc[name] for doc in documents))
        for name, _ in _FIELDS
        if name != "schema" and len({canonical_json_bytes(doc[name]) for doc in documents}) > 1
    )
